import{_ as t,c as a,o as r,ah as o}from"./chunks/framework.Ch_PcVtW.js";const S=JSON.parse('{"title":"VitePress","description":"","frontmatter":{"title":"VitePress"},"headers":[],"relativePath":"scripts/output/2_edited.md","filePath":"scripts/output/2_edited.md"}'),i={name:"scripts/output/2_edited.md"};function p(n,e,s,c,_,d){return r(),a("div",null,[...e[0]||(e[0]=[o('<h2 id="在持续进化的岁月底色里-镌刻着各自的信念——" tabindex="-1">在持续进化的岁月底色里，镌刻着各自的信念—— <a class="header-anchor" href="#在持续进化的岁月底色里-镌刻着各自的信念——" aria-label="Permalink to &quot;在持续进化的岁月底色里，镌刻着各自的信念——&quot;">​</a></h2><h2 id="一路追随-be-first-的《rockin-on-japan》-献上从过去通向未来的长传式访谈" tabindex="-1">一路追随 BE:FIRST 的《rockin&#39;on JAPAN》，献上从过去通向未来的长传式访谈 <a class="header-anchor" href="#一路追随-be-first-的《rockin-on-japan》-献上从过去通向未来的长传式访谈" aria-label="Permalink to &quot;一路追随 BE:FIRST 的《rockin&#39;on JAPAN》，献上从过去通向未来的长传式访谈&quot;">​</a></h2><p>2021 年，BE:FIRST 由选秀企划《THE FIRST》诞生，并于 11 月 3 日迎来主流出道 4 周年。在这之前的 10 月 29 日，组合发行了首张精选专辑《BE:ST》。4 年就推出精选，对一般艺人来说或许稍早；但当你看到曲目表上 30 余首歌曲时，就会立刻明白。刻在其中的多彩与多元，正是他们高密度岁月的足迹，也是进化的明证。</p><p>4 年前，BE:FIRST 在事务所社长兼制作人 SKY-HI 的引领下起步；如今，他们带着健康的自由感与旺盛的好奇心，正凭自己的双脚不断迈上新的台阶。从巨蛋巡演到世界巡演，再到体育场公演，演出规模持续扩大，这就是最直接的证明。更重要的是，这背后还有一段扎实的历程：成员们积极参与歌曲制作，亲手把“当下需要的声音”一点点抓到手里并做成作品。《来证明什么才是最高》是首张专辑《BE:1》主打曲《Scream》中的一句歌词。正如这句宣言，他们一路走来，始终在不断刷新并证明属于自己的“最高”。</p><p>在《BE:ST》发行这一时间点策划 BE:FIRST 特集时，我们最想做的一件事，是解开这段耀眼历史背后：每位成员当时究竟在想什么。</p><p>为了作为“最强进化团体”BE:FIRST 继续前行，他们究竟改变了什么，又如何守住了那些不曾改变的部分——其实在《rockin&#39;on JAPAN》，我们早在《BE:1》发行后的 2022 年秋就已启动成员个人专访连载，历时约半年。此次别册特集中，我们一边摘录他们当年各自说过的话，一边尝试做一次再次触及其内在信念的访谈（另外，各采访页面也重刊了 3 年前报道中的旧照，也请留意他们这些年的变化）。</p><p>为什么 BE:FIRST 是 BE:FIRST？为什么他们能持续证明“最高”？</p><p>我认为，这已经成为一组能够触及其真髓、独一无二的特集。 <br><br></p><p>（安田季那子）</p><p>采访：小川智宏 摄影：大野隼男</p>',10)])])}const T=t(i,[["render",p]]);export{S as __pageData,T as default};
